footer.css:
.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main {
	background: #ffffff;
	display: flex;
	color: #10171A;
	border-top: .1rem solid #d9d9d9;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-logo-container {
	width: 27.7rem;
	padding: 2rem 0;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-logo-container .sf-logo {
	max-width: 100%;
	padding: 1rem 1.4rem;
	display: block;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-logo-container .sf-logo-content {
	padding: 1rem 1.4rem;
	word-break: break-word;
	font-size: 1.2rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container {
	flex: 1;
	padding-top: 3.4rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container .sf-group {
	width: 22rem;
	padding: 0 1.4rem 3.2rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container .sf-group .sf-group-title {
	color: #10171A;
	font-size: 1.6rem;
	font-weight: bold;
	padding-bottom: 1.6rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container .sf-group .sf-link {
	padding-bottom: 1.6rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container .sf-group .sf-link a {
	display: inline-block;
	color: #10171A;
	opacity: .7;
	font-size: 1.4rem;
	word-break: break-word;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container .sf-group .sf-link a:hover {
	color: #10171A;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-main .sf-links-container .sf-group .sf-link a:focus {
	outline: .2rem solid #10171A;
	outline-offset: .5rem;
	box-shadow: none;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom {
	background: #ffffff;
	color: #10171A;
	font-size: 1.2rem;
	display: flex;
	border-top: .1rem solid #d9d9d9;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-left {
	flex: 1;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-left .sf-bottom-link a {
	color: #10171A;
	font-size: 1.2rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-left .sf-bottom-link a:hover {
	color: $footer-link-hover-color;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-left .sf-bottom-link a:focus {
	outline: .2rem solid #10171A;
	outline-offset: .5rem;
	box-shadow: none;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-right {
	display: flex;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-right .sf-social-icons {
	padding: 2.7rem 0;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-right .sf-social-icons .sf-social-icon {
	color: #10171A;
	padding: 0;
	margin: 0 .8rem;
	font-size: 2rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-right .sf-social-icons .sf-social-icon:focus {
	outline: .2rem solid #10171A;
	outline-offset: .5rem;
	box-shadow: none;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom-link, 
.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-copyright {
	display: inline-block;
	padding: 2.7rem 1.15rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .inline-block {
	display: inline-block;
}

.vce046d5773603010c94f54eb7df6a7ec .masonry-root {
	display: flex;
	flex-direction: column;
	flex-wrap: wrap;
}
@media screen and (-ms-high-contrast: active), (-ms-high-contrast: none) {

.vce046d5773603010c94f54eb7df6a7ec .masonry-root {
	max-height: 100% !important;
}

.vce046d5773603010c94f54eb7df6a7ec .masonry-root .masonry-cell {
	display: -ms-inline-flexbox;
	flex-direction: column;
	-ms-flex-wrap: wrap;
}

.vce046d5773603010c94f54eb7df6a7ec .masonry-root .masonry-cell .sf-group-title {
	width: 100%;
}

.vce046d5773603010c94f54eb7df6a7ec .masonry-root:after {
	content: "";
	clear: both;
	display: table;
}
}
