}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom {
	padding: 1.8rem 1.1rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-link {
	padding: 0 .8rem 1.1rem .8rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-right .sf-social-icons {
	flex: 1;
	padding: 0;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-right .sf-social-icons .sf-social-icon {
	margin: 0 .8rem .8rem .8rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-bottom-left {
	display: block;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-bottom .sf-copyright {
	padding: 0 1.8rem;
}

.vce046d5773603010c94f54eb7df6a7ec .scrub-footer .sf-links-container {
