function cdSurgeEventModal() {
	return {
		restrict: 'E',
template: '<div></div>',
		controller: function($scope, $sce, $location, $window, spModal) {
			var cache = $scope.data.currSurgeEventsCache;
			var userEvents = $scope.data.userAuthorizedEvents;
			onLoad();
			function onLoad() {
				if ($scope.isHomepage() && cache && userEvents && userEvents.length > 0) {
					openSpModal();
				}
			}
			function openSpModal() {
				var eventListStyle = 'display: flex; flex-direction: column; align-items: flex-start; gap: 10px;';
				var radioStyle = 'width: 16px; height: 24px;';
				var labelStyle = 'margin: auto;';
var message = '<div role="radiogroup" style="' + eventListStyle +'"><span>Happening now:</span>';
				userEvents.forEach(function (sysId, index) {
					var eventObj = cache[sysId];
					message += '<div style="display: inherit; align-items: flex-start; gap: 8px;" >';
					if (userEvents.length > 1) {
						message += '<input type="radio" name="surgeEvents" id="surgeEvent' + index + '" value=' + sysId + ' style="' + radioStyle + '">';
message += '<label for="surgeEvent' + index + '" style="' + labelStyle + '">' + eventObj.headline + '</label>';
					} else {
message += '<span>' + eventObj.headline + '</span>';
					}
message += '</div>';
				});
message += '</div>';
				spModal.open({
					title: 'Join your company event?',
					message: $sce.trustAsHtml(message),
					buttons: [
						{ label: 'No', cancel: true },
						{ label: 'Yes, go to event', primary: true, class: 'text-white' },
					],
				}).then(
					function() {
						var selected = document.querySelector('input[name="surgeEvents"]:checked');
						if (selected) {
							$location.search({'id': $scope.data.companyEventPageId, 'sys_id': selected.value});
						} else if (userEvents.length === 1) {
							$location.search({'id': $scope.data.companyEventPageId, 'sys_id': userEvents[0]});
						}
						$window.location.href = $location.absUrl();
					},
					function() {
						var ga = new GlideAjax('sn_cd.cd_CompanyEventsAJAX');
						ga.addParam('sysparm_name', 'addSurgeEventPortalRes');
						ga.addParam('sysparm_content_ids', JSON.stringify(userEvents));
						ga.getXMLAnswer(function() {
							$window.location.href = $location.absUrl();
						});
					}
				);
			}
		},
		controllerAs: 'c',
		bindToController: true
	};
}

