api.controller = function($scope, $rootScope, spUtil) {
  var c = this;
  c.expanded = !spUtil.isMobile();
  c.expand = function() { c.expanded = true; };


  function parseParams(search) {
    var params = {};
(search || '').replace(/^\?/, '').split('&').forEach(function(pair) {
      var parts = pair.split('=');
      if (parts[0]) params[decodeURIComponent(parts[0])] = decodeURIComponent(parts[1] || '');
    });
    return params;
  }


  var PAGE_MAP = {
    'exams_page': function() {
      return null;
    },
    'exam_details': function(params) {
      return [];
    },
    'exam_setup_page': function(params) {
      return [
        { label: 'Exam Details', url: '?id=exam_details&exam_id=' + params.exam_id }
      ];
    },
    'exam_questions_page': function(params) {
      if (params.sim_id) {
        var examId = sessionStorage.getItem('last_exam_id');
        return [
          { label: 'Exam Details', url: '?id=exam_details' + (examId ? '&exam_id=' + examId : '') }
        ];
      } else {
        return [
          { label: 'Exam Details', url: '?id=exam_details&exam_id=' + params.exam_id },
          { label: 'Exam Setup',   url: '?id=exam_setup_page&exam_id=' + params.exam_id }
        ];
      }
    }
  };


  var pageId    = $scope.page && $scope.page.id;
  var pageTitle = $scope.page && $scope.page.title;
  var params    = parseParams(window.location.search);

  if (pageId === 'exam_details' && params.exam_id) {
    sessionStorage.setItem('last_exam_id', params.exam_id);
  }

  var buildAncestors = PAGE_MAP[pageId];

  if (buildAncestors) {
    var ancestors = buildAncestors(params);

    if (ancestors !== null) {
      ancestors.push({ label: pageTitle, url: window.location.search });
      c.breadcrumbs = ancestors;
    }
  }


  var deregister = $rootScope.$on('sp.update.breadcrumbs', function(e, list) {
    c.breadcrumbs = list;
  });

  $scope.$on('$destroy', function() { deregister(); });
};

