widget.client_script:
api.controller = function($scope, $interval) {

  $scope.currentIndex    = 0;
  $scope.currentQuestion = null;
  $scope.isReview        = $scope.data.isReview;

  
  $scope.$watch('data.questions', function(questions) {
    if (questions && questions.length && !$scope.currentQuestion) {
      $scope.currentQuestion = questions[0];
    }
  });

  $scope.getProgress = function() {
    var total = $scope.data.questions.length;
    if (!total) return 0;
return ($scope.getAnsweredCount() / total) * 100;
  };

  $scope.isSelected = function(answer) {
    var q = $scope.currentQuestion;
    if (!q) return false;
    if (q.single_choice) {
      return q.selectedAnswer === answer.sys_id;
    }
    return q.selectedAnswers && q.selectedAnswers.indexOf(answer.sys_id) > -1;
  };

  $scope.toggleAnswer = function(answer) {
	console.log('abcdefg');
    if ($scope.isReview) return;
    var q = $scope.currentQuestion;
    if (!q.selectedAnswers) q.selectedAnswers = [];
    var index = q.selectedAnswers.indexOf(answer.sys_id);
    if (index > -1) {
      q.selectedAnswers.splice(index, 1);
    } else {
      if (q.selectedAnswers.length >= q.correct_count) {
        alert("You can only select " + q.correct_count + " options");
        return;
      }
      q.selectedAnswers.push(answer.sys_id);
    }
  };

  $scope.isMaxSelected = function(answer) {
    if ($scope.isReview) return true;
    var q = $scope.currentQuestion;
    if (!q.selectedAnswers) return false;
    if (q.selectedAnswers.indexOf(answer.sys_id) > -1) return false;
    return q.selectedAnswers.length >= q.correct_count;
  };

  $scope.isQuestionCorrect = function(q) {
    return $scope.isReview && q.answeredCorrectly;
  };

  $scope.isQuestionWrong = function(q) {
    return $scope.isReview && !q.answeredCorrectly;
  };

  $scope.nextQuestion = function() {
    if (!$scope.isReview) {
      var q = $scope.currentQuestion;
      if (!q.single_choice) {
        var selected = q.selectedAnswers ? q.selectedAnswers.length : 0;
        if (selected !== q.correct_count) {
          alert("You must select exactly " + q.correct_count + " options");
          return;
        }
      }
    }
    if ($scope.currentIndex < $scope.data.questions.length - 1) {
      $scope.currentIndex++;
      $scope.currentQuestion = $scope.data.questions[$scope.currentIndex];
    }
  };

  $scope.prevQuestion = function() {
    if ($scope.currentIndex > 0) {
      $scope.currentIndex--;
      $scope.currentQuestion = $scope.data.questions[$scope.currentIndex];
    }
  };

  $scope.goToQuestion = function(index) {
    $scope.currentIndex    = index;
    $scope.currentQuestion = $scope.data.questions[index];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  $scope.toggleReview = function() {
    if ($scope.isReview) return;
    $scope.currentQuestion.flagged = !$scope.currentQuestion.flagged;
  };

  $scope.getFlaggedQuestions = function() {
    return $scope.data.questions.filter(function(q) { return q.flagged; });
  };

  $scope.reportedQuestions = [];

  $scope.isReported = function(questionId) {
    return $scope.reportedQuestions.indexOf(questionId) > -1;
  };

  $scope.toggleReport = function() {
    var questionId = $scope.currentQuestion.sys_id;
    if ($scope.isReported(questionId)) return;

    $scope.server.get({
      action     : 'submit_report',
      question   : $scope.currentQuestion.text,
      questionId : questionId
    }).then(function(response) {
      if (response.data.report_result === 'success') {
        $scope.reportedQuestions.push(response.data.questionId);
      }
    });
  };

  $scope.isAnswered = function(q) {
    if (q.single_choice) return !!q.selectedAnswer;
    return q.selectedAnswers && q.selectedAnswers.length > 0;
  };

  $scope.getAnsweredCount = function() {
    return $scope.data.questions.filter($scope.isAnswered).length;
  };

  $scope.submitQuiz = function() {
    if ($scope.isReview) return;

    var total    = $scope.data.questions.length;
    var answered = $scope.getAnsweredCount();

    if (answered < total) {
alert("You must answer all questions (" + answered + "/" + total + ")");
      return;
    }

    for (var i = 0; i < $scope.data.questions.length; i++) {
      var q = $scope.data.questions[i];
      if (!q.single_choice) {
        var selected = q.selectedAnswers ? q.selectedAnswers.length : 0;
        if (selected !== q.correct_count) {
          alert("Question " + (i + 1) + " requires exactly " + q.correct_count + " answers");
          $scope.goToQuestion(i);
          return;
        }
      }
    }

    var flagged = $scope.getFlaggedQuestions();
    if (flagged.length > 0) {
      var confirmSubmit = confirm(
        "You have " + flagged.length + " question(s) marked for review. Submit anyway?"
      );
      if (!confirmSubmit) return;
    }

    $scope.server.get({
      action    : 'submit_exam',
      exam_id   : $scope.data.examId,
      questions : $scope.data.questions
    }).then(function(response) {
      if (response.data && response.data.result) {
        var simId = response.data.result.sim_id;
        if (!simId) {
          alert("Error: sim_id not returned");
          return;
        }
        window.location.href = "?id=exam_questions_page&sim_id=" + simId;
      }
    });
  };

};
